from pptx import Presentation
from pptx.enum.shapes import MSO_SHAPE_TYPE

prs = Presentation('/root/Awesome-Agent-Papers_processed.pptx')
slide_width = prs.slide_width
slide_height = prs.slide_height
print(f"Slide dimensions: {slide_width} x {slide_height} EMUs")
print(f"Total slides: {len(prs.slides)}")
print("="*100)

for i, slide in enumerate(prs.slides):
    print(f"\n--- Slide {i+1} (Layout: {slide.slide_layout.name}) ---")
    for j, shape in enumerate(slide.shapes):
        if shape.shape_type == MSO_SHAPE_TYPE.TEXT_BOX:
            print(f"  TEXT_BOX '{shape.name}':")
            print(f"    Position: left={shape.left}, top={shape.top}")
            print(f"    Size: width={shape.width}, height={shape.height}")
            print(f"    Centered: left + width/2 = {shape.left + shape.width//2} vs slide center = {slide_width//2}")
            print(f"    Bottom edge: {shape.top + shape.height} vs slide height: {slide_height}")
            for para in shape.text_frame.paragraphs:
                if para.text.strip():
                    print(f"    Text: '{para.text}'")
                    print(f"    Alignment: {para.alignment}")
                    for run in para.runs:
                        try:
                            color = str(run.font.color.rgb) if run.font.color.type is not None else 'None'
                        except:
                            color = 'N/A'
                        print(f"      Font: name={run.font.name}, size={run.font.size}, bold={run.font.bold}, color={color}")

    # Check last slide (Reference)
    if i == len(prs.slides) - 1:
        print(f"\n  === REFERENCE SLIDE ===")
        for shape in slide.shapes:
            if shape.has_text_frame:
                print(f"  Shape '{shape.name}':")
                for k, para in enumerate(shape.text_frame.paragraphs):
                    if para.text.strip():
                        print(f"    Para {k}: '{para.text}'")
                        # Check for auto-numbering
                        from pptx.oxml.ns import qn
                        pPr = para._p.find(qn('a:pPr'))
                        if pPr is not None:
                            buAutoNum = pPr.find(qn('a:buAutoNum'))
                            if buAutoNum is not None:
                                print(f"      Auto-numbering: type={buAutoNum.get('type')}")
